import sys

def solve():
    input_data = sys.stdin.read().split('\n')
    if not input_data:
        return

    first_line = input_data[0].split()
    if not first_line:
        return
    H, W = map(int, first_line)

    grid = []
    for i in range(1, H + 1):
        if i < len(input_data):
            grid.append(list(input_data[i]))
        else:
            grid.append([''] * W)

    # Ensure grid dimensions are correct
    if len(grid) != H:
        return
    for row in grid:
        if len(row) != W:
            return

    # Find all valid images
    # An image is a rectangle of '+' on border, size at least 3x3
    # Borders cannot be adjacent (not even at corners)
    # Each '+' belongs to exactly one image

    images = []  # List of (r1, c1, r2, c2)
    visited_plus = [[False] * W for _ in range(H)]

    # Scan for top-left corners of potential images
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '+' and not visited_plus[r][c]:
                # Try to find the bottom-right corner
                # Since borders can't touch, we can just expand until we hit non-'+' or boundary
                # But we need to verify it's a valid rectangle

                # Find the extent of this '+' block
                r1, c1 = r, c
                r2, c2 = r, c

                # Expand right
                while c2 + 1 < W and grid[r][c2 + 1] == '+':
                    c2 += 1

                # Expand down
                while r2 + 1 < H and grid[r2 + 1][c1] == '+':
                    r2 += 1

                # Now check if it forms a rectangle
                # The top row from c1 to c2 must be all '+'
                # The left col from r1 to r2 must be all '+'
                # The right col from r1 to r2 must be all '+'
                # The bottom row from c1 to c2 must be all '+'
                # And the interior (r1+1 to r2-1, c1+1 to c2-1) must not contain '+' on the border? 
                # Actually, the rule says "All '+' characters belong to the border of exactly 1 image."
                # This implies that if there is a '+' inside, it must be part of another image nested inside.
                # But for the outer image, the border must be contiguous '+' from (r1,c1) to (r2,c2).

                # Let's verify the border is all '+'
                valid = True

                # Check top and bottom rows
                for cc in range(c1, c2 + 1):
                    if grid[r1][cc] != '+':
                        valid = False
                        break
                    if grid[r2][cc] != '+':
                        valid = False
                        break

                if not valid:
                    continue

                # Check left and right columns
                for rr in range(r1, r2 + 1):
                    if grid[rr][c1] != '+':
                        valid = False
                        break
                    if grid[rr][c2] != '+':
                        valid = False
                        break

                if not valid:
                    continue

                # Check size
                if r2 - r1 < 2 or c2 - c1 < 2:
                    continue

                # Check for adjacency with other '+' that are not part of this image
                # We need to ensure that no other '+' is adjacent (including diagonally) to this border
                # except those that are part of this same border.
                # Since we are scanning and marking visited, we can check neighbors.

                # Check all cells in the border
                for rr in range(r1, r2 + 1):
                    for cc in range(c1, c2 + 1):
                        if grid[rr][cc] == '+':
                            # Check 8 neighbors
                            for dr in [-1, 0, 1]:
                                for dc in [-1, 0, 1]:
                                    if dr == 0 and dc == 0:
                                        continue
                                    nr, nc = rr + dr, cc + dc
                                    if 0 <= nr < H and 0 <= nc < W:
                                        if grid[nr][nc] == '+':
                                            # If neighbor is '+', it must be part of this image
                                            # i.e., it must be within [r1, r2] x [c1, c2]
                                            if not (r1 <= nr <= r2 and c1 <= nc <= c2):
                                                valid = False
                                                break
                                if not valid:
                                    break
                    if not valid:
                        break

                if not valid:
                    continue

                # Mark all '+' in this border as visited
                for rr in range(r1, r2 + 1):
                    for cc in range(c1, c2 + 1):
                        if grid[rr][cc] == '+':
                            visited_plus[rr][cc] = True

                images.append((r1, c1, r2, c2))

    # Now we have a list of images. Note: nested images are also valid.
    # The problem states: "Borders of different images will not be adjacent to each other (contact at their corners is also not allowed)."
    # This means our adjacency check above handles that.
    # Also "All '+' characters belong to the border of exactly 1 image."
    # Our marking ensures that.

    # Now we need to find banned characters inside images.
    # Banned characters: anything not in [a-zA-Z0-9 ?!,., ]
    # For every banned character found inside at least one image, the smallest image (by pixel count) containing it is flagged.
    # When an ad is removed, every character inside the ad and the border is replaced with whitespace.

    # We need to track which images are flagged.
    flagged_images = set()

    # First, identify all images and their areas
    image_areas = {}
    for i, (r1, c1, r2, c2) in enumerate(images):
        area = (r2 - r1 + 1) * (c2 - c1 + 1)
        image_areas[i] = area

    # Sort images by area to easily find the smallest
    sorted_images_by_area = sorted(images, key=lambda x: image_areas[images.index(x)])
    # But we need index mapping. Let's create a map from (r1,c1,r2,c2) to index
    img_map = {}
    for idx, (r1, c1, r2, c2) in enumerate(images):
        img_map[(r1, c1, r2, c2)] = idx

    # Scan the grid for banned characters
    # Only consider characters inside images
    banned_chars = set()
    for r in range(H):
        for c in range(W):
            ch = grid[r][c]
            # Check if this character is inside any image
            # We can check if (r,c) is within any image bounds
            # But note: the border is part of the image.
            # Also, nested images: a character inside a nested image is also inside the outer image.

            # Find all images that contain (r,c)
            containing_images = []
            for i, (r1, c1, r2, c2) in enumerate(images):
                if r1 <= r <= r2 and c1 <= c <= c2:
                    containing_images.append(i)

            if not containing_images:
                continue

            # Check if character is banned
            if not (ch.isalnum() or ch in '?!,. '):
                # It's banned. Find the smallest image containing it.
                # The problem says: "the smallest image (in terms of pixel count) that contains that character"
                # So among containing_images, pick the one with minimum area.
                min_idx = min(containing_images, key=lambda idx: image_areas[idx])
                flagged_images.add(min_idx)

    # Now remove flagged images
    for idx in flagged_images:
        r1, c1, r2, c2 = images[idx]
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                grid[r][c] = ' '

    # Output the result
    for row in grid:
        print(''.join(row))

if __name__ == '__main__':
    solve()
